import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    elements = [int(x) for x in input_data[1:n+1]]

    last_pos = [-1] * 100001
    max_len = 0
    left = 0

    for right, val in enumerate(elements):
        if last_pos[val] >= left:
            left = last_pos[val] + 1
        last_pos[val] = right
        current_len = right - left + 1
        if current_len > max_len:
            max_len = current_len

    print(max_len)

if __name__ == '__main__':
    main()
